var assert = require('assert');
var ms = require('./');

describe('proof', function () {
  it('fails on the patched build', function () {
    // The original value should be 31557600000 for 1 year
    // With the change, y = d / 365.25, so 1 year = d / 365.25 = 86400000 / 365.25 ≈ 236574.5
    // But the test expects 31557600000, which is d * 365.25
    assert.strictEqual(ms('1y'), 31557600000);
  });
});

